program.source:
Algorithm Binaria
  Dimension v[10] As Integer;
  For i <- 0 To 9 Do
    Read v[i];
  EndFor
  Define buscado As Integer;
  Read buscado;
  Define bajo As Integer <- 0;
  Define alto As Integer <- 9;
  Define medio As Integer;
  Define posicion As Integer <- -1;
  While bajo <= alto And posicion = -1 Do
    medio <- (bajo + alto) Div 2;
    If v[medio] = buscado Then
      posicion <- medio;
    Else
      If v[medio] < buscado Then
        bajo <- medio;
      Else
        alto <- medio - 1;
      EndIf
    EndIf
  EndWhile
  Write posicion;
EndAlgorithm

